# Nginx TCP 优化配置
upstream backend_tcp {
    server 10.0.0.10:8080;
    server 10.0.0.11:8080;

    # 连接池设置
    keepalive 32;
    keepalive_requests 1000;
    keepalive_timeout 60s;

    # 负载均衡算法
    least_conn;
}

server {
    listen 8080;

    # TCP 优化参数
    tcp_nodelay on;
    tcp_nopush on;

    proxy_pass backend_tcp;
    proxy_timeout 90s;
    proxy_responses 1;

    # 健康检查
    health_check interval=5s fails=3 passes=2;
}
